function getSkd(id) { const entries = data.tests[id] || []; if (!entries.length) return { twk: null, tiu: null, tkp: null, total: null, pass: false, count: 0 }; const twk = average(entries.map(test => test.twk)); const tiu = average(entries.map(test => test.tiu)); const tkp = average(entries.map(test => test.tkp)); return { twk, tiu, tkp, total: twk + tiu + tkp, pass: twk >= 65 && tiu >= 80 && tkp >= 156, count: entries.length }; }
